document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('input.input-qty').forEach(function(input){var parent=input.parentNode;var qtyButtons=parent.querySelectorAll('.is-form');var min=Number(input.getAttribute('min'))||0;var max=Number(input.getAttribute('max'))||Infinity;var d=min;qtyButtons.forEach(function(button){button.addEventListener('click',function(){if(this.classList.contains('minus')){if(d>min)d-=1}else if(this.classList.contains('plus')){var x=Number(input.value)+1;if(x<=max)d+=1}
input.setAttribute('value',d);input.value=d;var event=new Event('keyup');input.dispatchEvent(event)})})});document.querySelectorAll('.form-request .toggle-dropdown').forEach(function(button){button.addEventListener('click',function(event){event.preventDefault();document.querySelectorAll('.form-request .dropdown-content').forEach(function(dropdown){dropdown.style.display='none'});this.nextElementSibling.style.display='block';this.nextElementSibling.style.transition='all 0.3s';this.nextElementSibling.style.height='auto'})});document.querySelectorAll('.form-request .dropdown-title').forEach(function(title){title.addEventListener('click',function(event){event.preventDefault();document.querySelectorAll('.form-request .dropdown-content').forEach(function(dropdown){dropdown.style.display='none'})})});document.querySelectorAll('.form-request .btn-close').forEach(function(button){button.addEventListener('click',function(event){event.preventDefault();this.closest('.dropdown-content').style.display='none'})});document.addEventListener('click',function(event){var isDropdown=event.target.closest('.form-request .dropdown-content');var isToggle=event.target.closest('.form-request .toggle-dropdown');if(!isDropdown&&!isToggle){document.querySelectorAll('.form-request .dropdown-content').forEach(function(dropdown){dropdown.style.display='none'})}});document.querySelectorAll('.form-request .destination-group input[type=checkbox]').forEach(function(checkbox){checkbox.addEventListener('change',function(event){var countries=Array.from(document.querySelectorAll('.form-request .destination-group input[type=checkbox]:checked')).map(function(checkbox){return checkbox.dataset.label});var countries_ids=Array.from(document.querySelectorAll('.form-request .destination-group input[type=checkbox]:checked')).map(function(checkbox){return checkbox.value});document.querySelector('.form-request .destination-input-hidden').value=countries_ids.join(',');document.querySelector('.form-request .destination-input').value=countries.join(', ')})});document.querySelectorAll('.form-request .companion-group .input-qty').forEach(function(input){input.addEventListener('keyup',function(event){var text='';var adultLabel=document.querySelector('.form-request .companion-group .adult-qty').dataset.label;var adultQty=document.querySelector('.form-request .companion-group .adult-qty').value;var childLabel=document.querySelector('.form-request .companion-group .child-qty').dataset.label;var childQty=document.querySelector('.form-request .companion-group .child-qty').value;var infantLabel=document.querySelector('.form-request .companion-group .infant-qty').dataset.label;var infantQty=document.querySelector('.form-request .companion-group .infant-qty').value;if(adultQty>0){text+=adultLabel+': '+adultQty+', '}
if(childQty>0){text+=childLabel+': '+childQty+', '}
if(infantQty>0){text+=infantLabel+': '+infantQty+', '}
document.querySelector('.form-request .companion-input').value=text.slice(0,-2)})});document.querySelectorAll('.form-request .duration-group input[type=number]').forEach(function(input){input.addEventListener('keyup',function(event){var text='';var from=Number(document.querySelector('.form-request .duration-group input.from').value);var daysText=document.querySelector('.form-request .duration-group .days-text').textContent;if(from>0){text=from+' '+daysText}
document.querySelector('.form-request .duration-input').value=text})});document.querySelectorAll('.form-request .budget-group .dropdown-content input').forEach(function(input){input.addEventListener('keyup',function(event){updateBudgetInput()});input.addEventListener('change',function(event){updateBudgetInput()})});function updateBudgetInput(){var text='';var numberLabel=document.querySelector('.form-request .budget-group input[type=number]').dataset.label;var number=document.querySelector('.form-request .budget-group input[type=number]').value;var flights=document.querySelector('.form-request .budget-group input[type=radio]:checked').dataset.label;if(number>0){text=number+' '+numberLabel+','+flights}
document.querySelector('.form-request .budget-input-hidden').value=number;document.querySelector('.form-request .budget-input').value=text}})